pub proof fn lemma_always_there_is_no_request_msg_to_external_from_controller(
    spec: TempPred<ClusterState>, cluster: Cluster, controller_id: int,
)
requires
    spec.entails(lift_state(cluster.init())),
    spec.entails(always(lift_action(cluster.next()))),
    cluster.type_is_installed_in_cluster::<VReplicaSetView>(),
    cluster.controller_models.contains_pair(controller_id, vrs_controller_model()),
ensures
    spec.entails(always(lift_state(Cluster::there_is_no_request_msg_to_external_from_controller(controller_id)))),
{
    // Key fact: the vreplicaset reconciler never produces an external request.
    // (It only ever returns RequestView::KRequest(...) or None.)
    assert(forall |vrs: VReplicaSetView, resp_o: Option<ResponseView<VoidERespView>>, state: VReplicaSetReconcileState|
        #[trigger] (VReplicaSetReconciler::reconcile_core(vrs, resp_o, state).1)
            match VReplicaSetReconciler::reconcile_core(vrs, resp_o, state).1 {
                None => true,
                Some(RequestView::KRequest(_)) => true,
                Some(RequestView::ExternalRequest(_)) => false,
            }
    );

    let inv = Cluster::there_is_no_request_msg_to_external_from_controller(controller_id);

    // Apply the standard temporal-logic invariant strengthening rule.
    init_invariant(
        spec,
        cluster.init(),
        cluster.next(),
        inv,
    );
}
}

